 16	export function activate(context: vscode.ExtensionContext) {
 17	  outputChannel = vscode.window.createOutputChannel("Consilium");
 18	
 19	  enableLogs("consilium-sdk:*");
 20	  setLogSink((...args: any[]) => {
 21	    handlerLog.log("SDK", { message: util.format(...args).replace(/\x1b\[[0-9;]*m/g, "") });
 22	
 23	    const message = util.format(...args).replace(/\x1b\[[0-9;]*m/g, "");
 24	    outputChannel.appendLine(message);
 25	  });
 26	  handlerLog.log("Consilium SDK logs enabled");
 27	
 28	  const remoteInfo = vscode.env.remoteName ? ` (remote: ${vscode.env.remoteName})` : "";
 29	  log(`Consilium extension activating...${remoteInfo}`);
 30	
 31	  initCLIManager(context);
 32	
 33	  // Remove title-generation temp sessions leaked by older builds.
 34	  cleanupStaleTitleSessions();
 35	
 36	  provider = new ConsiliumWebviewProvider(context.extensionUri, context.workspaceState, context.globalState, () => outputChannel.show());
 37	
 38	  // Initialize context state
