 40	function resolveSubagentRoleOverrides(
 41	  workspaceRoot: string | null,
 42	  extensionRoot: string,
 43	): Record<string, string> | undefined {
 44	  if (!workspaceRoot || !extensionRoot) {
 45	    return undefined;
 46	  }
 47	
 48	  const workspaceAgentsDir = path.join(workspaceRoot, '.consilium', 'agents');
 49	  const workspaceRolePath = path.join(workspaceAgentsDir, 'plan_editor_role.md');
 50	
 51	  // 1. Workspace-local role file takes precedence.
 52	  if (fs.existsSync(workspaceRolePath)) {
 53	    console.log(`[Bridge] Using workspace plan_editor role override: ${workspaceRolePath}`);
 54	    return { plan_editor: workspaceRolePath };
 55	  }
 56	
 57	  // 2. Seed from built-in profile template if available.
 58	  const profile = VSCodeSettings.agentProfile;
 59	  if (profile) {
 60	    const profileRolePath = path.join(extensionRoot, 'resources', 'agent-profiles', profile, 'plan_editor_role.md');
 61	    if (fs.existsSync(profileRolePath)) {
 62	      fs.mkdirSync(workspaceAgentsDir, { recursive: true });
 63	      fs.copyFileSync(profileRolePath, workspaceRolePath);
 64	      console.log(`[Bridge] Seeded workspace plan_editor role from profile ${profile}: ${workspaceRolePath}`);
 65	      return { plan_editor: workspaceRolePath };
 66	    }
 67	  }
 68	
 69	  // 3. No override; use CLI built-in default.
 70	  console.log('[Bridge] No workspace/profile plan_editor role override found; using CLI default');
 71	  return undefined;
 72	}
