 86	/** Close a session with a timeout guard to prevent hung processes from leaking. */
 87	async function safeCloseSession(session: Session, label: string, timeoutMs = 5000): Promise<void> {
 88	  const closePromise = session.close();
 89	  let timer: NodeJS.Timeout | undefined;
 90	  const timeoutPromise = new Promise<void>((_, reject) => {
 91	    timer = setTimeout(() => reject(new Error(`close() timed out after ${timeoutMs}ms`)), timeoutMs);
 92	  });
 93	  try {
 94	    await Promise.race([closePromise, timeoutPromise]);
 95	  } catch (err) {
 96	    sessionLog.error("safeCloseSession failed", { label, error: String(err) });
 97	  } finally {
 98	    clearTimeout(timer);
 99	  }
100	}
