 52	export function compareVersion(a: string, b: string): number {
 53	  const v1 = a.split(".").map(Number);
 54	  const v2 = b.split(".").map(Number);
 55	  for (let i = 0; i < Math.max(v1.length, v2.length); i++) {
 56	    const diff = (v1[i] || 0) - (v2[i] || 0);
 57	    if (diff !== 0) {
 58	      return diff;
 59	    }
 60	  }
 61	  return 0;
 62	}
