 64	export class CLIManager {
 65	  private extensionBinPath: string;
 66	  private consiliumPath: string;
 67	  private uvPath: string;
 68	
 69	  constructor(private ctx: vscode.ExtensionContext) {
 70	    const globalBin = path.join(ctx.globalStorageUri.fsPath, "bin");
 71	    this.extensionBinPath = path.join(ctx.extensionUri.fsPath, "bin", "consilium");
 72	    this.consiliumPath = path.join(globalBin, "consilium");
 73	    this.uvPath = path.join(globalBin, "uv");
 74	  }
 75	
 76	  getExecutablePath(): string {
 77	    const custom = vscode.workspace.getConfiguration("consilium").get<string>("executablePath");
 78	    if (custom) {
 79	      return custom;
 80	    }
 81	
 82	    const installed = readInstalled(this.consiliumPath);
 83	    const info = getPlatformInfo();
 84	    const filename = installed?.type === "uv" ? info.wrapper : info.exe;
 85	    return path.join(this.consiliumPath, filename);
 86	  }
 87	
 88	  async checkInstalled(workDir: string): Promise<CLICheckResult> {
 89	    const resolved = { isCustomPath: this.isCustomPath(), path: this.getExecutablePath() };
 90	
 91	    try {
 92	      if (!(await this.ensureCLI())) {
 93	        return { ok: false, resolved, error: { type: "extract_failed", message: "Failed to install CLI" } };
 94	      }
 95	    } catch (err) {
 96	      cliLog.error("Error ensuring CLI", { error: String(err) });
 97	      return { ok: false, resolved, error: { type: "extract_failed", message: errorText(err) } };
 98	    }
 99	
100	    return this.verify(workDir, resolved);
101	  }
102	
103	  private isCustomPath(): boolean {
104	    return !!vscode.workspace.getConfiguration("consilium").get<string>("executablePath");
105	  }
106	
107	  private async ensureCLI(): Promise<boolean> {
108	    if (this.isCustomPath()) {
109	      return true;
110	    }
111	
112	    const manifest = readManifest(this.extensionBinPath);
113	    if (!manifest) {
114	      return false;
115	    }
116	
117	    const platform = getPlatformKey();
118	    const installed = readInstalled(this.consiliumPath);
119	
120	    if (installed?.version === manifest.version && installed?.platform === platform) {
121	      return true;
122	    }
123	
124	    const asset = manifest.platforms[platform];
125	    cliLog.log("Installing CLI", { platform, asset, installed, manifest });
126	
127	    if (asset) {
128	      if (manifest.bundledPlatform === platform) {
129	        cliLog.log("Extracting bundled CLI", { platform });
130	        const archiveExt = asset.filename.endsWith(".zip") ? "zip" : "tar.gz";
131	
132	        cliLog.log("Extracting bundled CLI with archive", { platform, extensionBinPath: this.extensionBinPath, archiveExt });
133	        extractBundledCLI(path.join(this.extensionBinPath, `archive.${archiveExt}`), this.consiliumPath);
134	        cliLog.log("Bundled CLI extracted", { platform });
135	
136	      } else {
137	        cliLog.log("Platform not matched bundled, downloading", { platform });
138	        vscode.window.showInformationMessage(`Downloading Consilium CLI for ${platform}...`);
139	        await downloadAndInstallCLI(asset, this.consiliumPath);
140	      }
141	      writeInstalled(this.consiliumPath, { version: manifest.version, platform, type: "native" });
142	    } else {
143	      cliLog.log("Platform not supported natively, installing via uv", { platform });
144	      vscode.window.showInformationMessage(`Native CLI not available for ${platform}. Installing via uv (first run may take a moment)...`);
145	      await downloadAndInstallUV(this.uvPath);
146	      copyUVWrapper(this.ctx.extensionUri.fsPath, this.consiliumPath);
147	      writeInstalled(this.consiliumPath, { version: manifest.version, platform, type: "uv" });
148	    }
149	
150	    return true;
151	  }
152	
153	  private async verify(workDir: string, resolved: { isCustomPath: boolean; path: string }): Promise<CLICheckResult> {
154	    const execPath = this.getExecutablePath();
155	
156	    let cliVersion: string;
157	    let wireVersion: string;
158	    try {
159	      const info = await this.getInfo(execPath);
160	      cliVersion = info.consilium_cli_version || info.consilium_version || "";
161	      wireVersion = info.wire_protocol_version;
162	    } catch (err) {
163	      cliLog.error("Error getting CLI info", { error: String(err) });
164	      return { ok: false, resolved, error: { type: "not_found", message: errorText(err) } };
165	    }
166	
167	    if (compareVersion(cliVersion, MIN_CLI_VERSION) < 0) {
168	      cliLog.error("CLI version too low", { cliVersion, minVersion: MIN_CLI_VERSION });
169	      return { ok: false, resolved, error: { type: "version_low", message: `CLI ${cliVersion} < ${MIN_CLI_VERSION}` } };
170	    }
171	    if (compareVersion(wireVersion, MIN_WIRE_VERSION) < 0) {
172	      cliLog.error("Wire protocol version too low", { wireVersion, minVersion: MIN_WIRE_VERSION });
173	      return { ok: false, resolved, error: { type: "version_low", message: `Wire ${wireVersion} < ${MIN_WIRE_VERSION}` } };
174	    }
175	
176	    try {
177	      const initResult = await this.verifyWire(execPath, workDir);
178	      return { ok: true, resolved, slashCommands: initResult.slash_commands };
179	    } catch (err) {
180	      cliLog.error("Error verifying wire protocol", { error: String(err) });
181	      return { ok: false, resolved, error: { type: "protocol_error", message: errorText(err) } };
182	    }
183	  }
184	
185	  private async getInfo(execPath: string): Promise<{ consilium_cli_version?: string; consilium_version?: string; wire_protocol_version: string }> {
186	    const { executable: actualExec, args: actualArgs } = spawnWindowsSafe(execPath, ["info", "--json"]);
187	    const { stdout } = await execAsync(actualExec, actualArgs);
188	    return JSON.parse(stdout);
189	  }
190	
191	  private async verifyWire(execPath: string, workDir: string): Promise<InitializeResult> {
192	    const client = new ProtocolClient();
193	    try {
194	      return await client.start({ sessionId: undefined, workDir, executablePath: execPath });
195	    } finally {
196	      await client.stop();
197	    }
198	  }
199	}

