30	  // Safe-guard args with spaces or special characters
31	  // If arg contains spaces or quotes, wrap it in double quotes and escape existing double quotes
32	  const safeArgs = (args || []).map((arg) => (/[\s"']/.test(arg) ? `"${arg.replace(/"/g, '\\"')}"` : arg));
