41	const addInputHistory: Handler<{ text: string }, { ok: boolean }> = async ({ text }, ctx) => {
42	  const history = ctx.workspaceState.get<string[]>(INPUT_HISTORY_KEY, []);
43	  // 避免重复添加相同的最近一条
44	  if (history[history.length - 1] !== text) {
45	    history.push(text);
46	    if (history.length > MAX_HISTORY_SIZE) {
47	      history.shift();
48	    }
49	    await ctx.workspaceState.update(INPUT_HISTORY_KEY, history);
50	  }
51	  return { ok: true };
52	};
