 84	function prependSystemContext(content: string | ContentPart[], ctx: string): string | ContentPart[] {
 85	  if (!ctx) {
 86	    return content;
 87	  }
 88	
 89	  if (typeof content === "string") {
 90	    return content + "\n" + ctx;
 91	  }
 92	
 93	  const idx = content.findIndex((p) => p.type === "text");
 94	  if (idx >= 0) {
 95	    const copy = [...content];
 96	    const part = copy[idx] as { type: "text"; text: string };
 97	    copy[idx] = { type: "text", text: ctx + part.text };
 98	    return copy;
 99	  }
100	
101	  return [{ type: "text", text: ctx }, ...content];
102	}
