112	  let content = "";
113	  if (fs.existsSync(absolutePath)) {
114	    try {
115	      content = fs.readFileSync(absolutePath, "utf-8");
116	    } catch {
117	      // File unreadable, use empty baseline (for new files)
118	    }
119	  }
