 42	const IGNORE_EXT = new Set([".lock", ".log", ".map", ".min.js", ".min.css", ".chunk.js", ".chunk.css"]);
 43	
 44	function shouldIgnore(name: string): boolean {
 45	  if (IGNORE_DIRS.has(name)) {
 46	    return true;
 47	  }
 48	  const ext = path.extname(name).toLowerCase();
 49	  return IGNORE_EXT.has(ext);
 50	}
 51	
 52	const SEARCH_EXCLUDE = `{${[...IGNORE_DIRS].map((d) => `**/${d}`).join(",")}}`;
 53	
 54	interface ViewState {
 55	  sessionId: string | null;
 56	  trackedFiles: Set<string>;
 57	}
 58	
 59	export class FileManager {
 60	  private viewStates = new Map<string, ViewState>();
 61	  private disposables: vscode.Disposable[] = [];
 62	
 63	  constructor(
 64	    private getWorkDir: () => string | null,
 65	    private broadcast: BroadcastFn,
 66	  ) {
 67	    // Watch for file changes
 68	    const watcher = vscode.workspace.createFileSystemWatcher("**/*");
 69	
 70	    watcher.onDidChange((uri) => this.onFileChange(uri));
 71	    watcher.onDidCreate((uri) => this.onFileChange(uri));
 72	    watcher.onDidDelete((uri) => this.onFileChange(uri));
 73	
 74	    this.disposables.push(watcher);
 75	  }
 76	
 77	  private getViewState(webviewId: string): ViewState {
 78	    let state = this.viewStates.get(webviewId);
 79	    if (!state) {
 80	      state = { sessionId: null, trackedFiles: new Set() };
 81	      this.viewStates.set(webviewId, state);
 82	    }
 83	    return state;
 84	  }
 85	
 86	  setSessionId(webviewId: string, sessionId: string): void {
 87	    this.getViewState(webviewId).sessionId = sessionId;
 88	  }
 89	
 90	  getSessionId(webviewId: string): string | null {
 91	    return this.getViewState(webviewId).sessionId;
 92	  }
 93	
 94	  trackFile(webviewId: string, absolutePath: string): void {
 95	    this.getViewState(webviewId).trackedFiles.add(absolutePath);
 96	  }
 97	
 98	  getTracked(webviewId: string): Set<string> {
 99	    return this.getViewState(webviewId).trackedFiles;
100	  }
101	
102	  clearTracked(webviewId: string): void {
103	    this.getViewState(webviewId).trackedFiles.clear();
104	  }
105	
106	  disposeView(webviewId: string): void {
107	    this.viewStates.delete(webviewId);
108	  }
109	
110	  private async onFileChange(uri: vscode.Uri): Promise<void> {
111	    const workDir = this.getWorkDir();
112	    if (!workDir) {
113	      return;
114	    }
115	
116	    const absolutePath = uri.fsPath;
117	
118	    for (const [webviewId, state] of this.viewStates) {
119	      if (!state.sessionId || !state.trackedFiles.has(absolutePath)) {
120	        continue;
121	      }
122	
123	      const changes = await BaselineManager.getChanges(workDir, state.sessionId, state.trackedFiles);
124	      this.broadcast(Events.FileChangesUpdated, changes, webviewId);
125	    }
126	  }
127	
128	  async searchFiles(query?: string): Promise<ProjectFile[]> {
129	    query = query ? buildCaseInsensitiveGlobLiteral(query) : "";
130	    const pattern = query ? `**/*${query}*` : "**/*";
131	    const files = await vscode.workspace.findFiles(pattern, SEARCH_EXCLUDE, 200);
132	    return files.map((uri) => ({
133	      path: vscode.workspace.asRelativePath(uri),
134	      name: path.basename(uri.fsPath),
135	      isDirectory: false,
136	    }));
137	  }
138	
139	  async listDirectory(workDir: string, directory: string): Promise<ProjectFile[]> {
140	    const dirPath = directory ? path.join(workDir, directory) : workDir;
141	    try {
142	      const entries = await fs.promises.readdir(dirPath, { withFileTypes: true });
143	      return entries
144	        .filter((e) => !shouldIgnore(e.name))
145	        .map((e) => ({
146	          path: directory ? path.join(directory, e.name) : e.name,
147	          name: e.name,
148	          isDirectory: e.isDirectory(),
149	        }))
150	        .sort((a, b) => (a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1));
151	    } catch {
152	      return [];
153	    }
154	  }
155	
156	  dispose(): void {
157	    for (const d of this.disposables) {
158	      d.dispose();
159	    }
160	    this.disposables = [];
161	    this.viewStates.clear();
162	  }
163	}

