 75	class TurnImpl implements Turn {
 76	  readonly result: Promise<RunResult>;
 77	  private resolveResult: (result: RunResult) => void;
 78	  private rejectResult: (error: Error) => void;
 79	  private interrupted = false;
 80	
 81	  constructor(
 82	    private getClient: () => Promise<ProtocolClient>,
 83	    private getCurrentClient: () => ProtocolClient | null,
 84	    private getNextPending: () => (string | ContentPart[]) | undefined,
 85	    private clearPending: () => void,
 86	    private onComplete: () => void,
 87	  ) {
 88	    let resolve!: (result: RunResult) => void;
 89	    let reject!: (error: Error) => void;
 90	    this.result = new Promise<RunResult>((res, rej) => {
 91	      resolve = res;
 92	      reject = rej;
 93	    });
 94	    this.result.catch(() => {});
 95	    this.resolveResult = resolve;
 96	    this.rejectResult = reject;
 97	  }
 98	
 99	  async *[Symbol.asyncIterator](): AsyncIterator<StreamEvent, RunResult, undefined> {
100	    try {
101	      let result: RunResult | undefined;
102	      let content: string | ContentPart[] | undefined;
103	      while (!this.interrupted && (content = this.getNextPending()) !== undefined) {
104	        result = yield* this.processOne(content);
105	      }
106	      this.onComplete();
107	      this.resolveResult(result!);
108	      return result!;
109	    } catch (err) {
110	      this.onComplete();
111	      this.rejectResult(err as Error);
112	      throw err;
113	    }
114	  }
115	
116	  private async *processOne(content: string | ContentPart[]): AsyncGenerator<StreamEvent, RunResult, undefined> {
117	    const client = await this.getClient();
118	    const stream = client.sendPrompt(content);
119	    for await (const event of stream.events) {
120	      yield event;
121	    }
122	    return await stream.result;
123	  }
124	
125	  async interrupt(): Promise<void> {
126	    this.interrupted = true;
127	    this.clearPending();
128	    const client = this.getCurrentClient();
129	    if (client?.isRunning) {
130	      return client.sendCancel();
131	    }
132	  }
133	
134	  async approve(requestId: string, response: ApprovalResponse): Promise<void> {
135	    const client = this.getCurrentClient();
136	    if (!client?.isRunning) {
137	      throw new SessionError("SESSION_CLOSED", "Cannot approve: no active client");
138	    }
139	    return client.sendApproval(requestId, response);
140	  }
141	
142	  async respondQuestion(rpcRequestId: string, questionRequestId: string, answers: Record<string, string>): Promise<void> {
143	    const client = this.getCurrentClient();
144	    if (!client?.isRunning) {
145	      throw new SessionError("SESSION_CLOSED", "Cannot respond to question: no active client");
146	    }
147	    return client.sendQuestionResponse(rpcRequestId, questionRequestId, answers);
148	  }
149	
150	  async steer(content: string | ContentPart[]): Promise<void> {
151	    const client = this.getCurrentClient();
152	    if (!client?.isRunning) {
153	      throw new SessionError("SESSION_CLOSED", "Cannot steer: no active client");
154	    }
155	    return client.sendSteer(content);
156	  }
157	}
