159	class SessionImpl implements Session {
160	  private readonly _sessionId: string;
161	  private readonly _workDir: string;
162	  private readonly _clientInfo?: ClientInfo;
163	
164	  private _model: string | undefined;
165	  private _thinking: boolean;
166	  private _yoloMode: boolean;
167	  private _doMode: boolean;
168	  private _executable: string;
169	  private _env: Record<string, string>;
170	  private _externalTools: ExternalTool[];
171	  private _agentFile?: string;
172	  private _subagentSystemPrompts?: Record<string, string>;
173	  private _skillsDir?: string;
174	  private _shareDir?: string;
175	  private _generationOverrides?: GenerationOverrides;
176	  private _slashCommands: SlashCommandInfo[] = [];
177	  private _planMode: boolean = false;
178	
179	  private _state: SessionState = "idle";
180	
181	  private client: ProtocolClient | null = null;
182	  private activeConfig: ActiveConfig | null = null;
183	  private currentTurn: TurnImpl | null = null;
184	  private pendingMessages: (string | ContentPart[])[] = [];
185	
186	  constructor(options: SessionOptions) {
187	    this._sessionId = options.sessionId ?? crypto.randomUUID();
188	    this._workDir = options.workDir;
189	    this._model = options.model;
190	    this._thinking = options.thinking ?? false;
191	    this._yoloMode = options.yoloMode ?? false;
192	    this._doMode = options.doMode ?? false;
193	    this._executable = options.executable ?? "consilium";
194	    this._env = options.env ?? {};
