197	    this._subagentSystemPrompts = options.subagentSystemPrompts;
198	    this._skillsDir = options.skillsDir;
199	    this._shareDir = options.shareDir;
200	    this._clientInfo = options.clientInfo;
201	    this._generationOverrides = options.generationOverrides;
