206	  get sessionId(): string {
207	    return this._sessionId;
208	  }
209	  get workDir(): string {
210	    return this._workDir;
211	  }
212	  get state(): SessionState {
213	    return this._state;
214	  }
215	  get slashCommands(): SlashCommandInfo[] {
216	    return this._slashCommands;
217	  }
