264	  async setPlanMode(enabled: boolean): Promise<boolean> {
265	    if (this._state === "closed") {
266	      throw new SessionError("SESSION_CLOSED", "Session is closed");
267	    }
268	    if (!this.client?.isRunning) {
269	      throw new SessionError("SESSION_CLOSED", "Cannot set plan mode: no active client");
270	    }
271	    const result = await this.client.sendSetPlanMode(enabled);
272	    this._planMode = result.plan_mode;
273	    return this._planMode;
274	  }
275	
276	  prompt(content: string | ContentPart[]): Turn {
277	    if (this._state === "closed") {
278	      throw new SessionError("SESSION_CLOSED", "Session is closed");
279	    }
280	
281	    this.pendingMessages.push(content);
282	    log.session("Queued prompt, pending: %d", this.pendingMessages.length);
283	
284	    if (this._state === "active" && this.currentTurn) {
285	      return this.currentTurn;
286	    }
287	
288	    this._state = "active";
289	    this.currentTurn = new TurnImpl(
290	      () => this.getClientWithConfigCheck(),
291	      () => this.client,
292	      () => this.pendingMessages.shift(),
293	      () => {
294	        this.pendingMessages = [];
295	      },
296	      () => {
297	        if (this._state === "active") {
298	          this._state = "idle";
299	        }
300	        this.currentTurn = null;
301	        log.session("Turn completed, state: %s", this._state);
302	      },
303	    );
304	
305	    return this.currentTurn;
306	  }
307	
308	  async close(): Promise<void> {
309	    if (this._state === "closed") {
310	      return;
311	    }
312	
313	    log.session("Closing session %s", this._sessionId);
314	    this._state = "closed";
315	    this.currentTurn = null;
316	    this.pendingMessages = [];
317	
318	    if (this.client) {
319	      try {
320	        await this.client.stop();
321	      } catch (err) {
322	        log.session("Error during close: %O", err);
323	      }
324	      this.client = null;
325	      this.activeConfig = null;
326	    }
327	  }
328	
329	  [Symbol.asyncDispose](): Promise<void> {
330	    return this.close();
331	  }
332	
333	  private async getClientWithConfigCheck(): Promise<ProtocolClient> {
334	    const currentConfig = this.snapshotConfig();
335	
336	    if (this.client?.isRunning && this.activeConfig && !this.configChanged(currentConfig)) {
337	      return this.client;
338	    }
339	
340	    // Config changed or no client, restart
341	    if (this.client) {
342	      log.session("Config changed, restarting client");
343	      await this.client.stop();
344	      this.client = null;
345	    }
346	
347	    this.client = new ProtocolClient();
348	    const envVars = this._shareDir ? { KIMI_SHARE_DIR: this._shareDir, ...this._env } : this._env;
349	    const initResult = await this.client.start({
350	      sessionId: this._sessionId,
351	      workDir: this._workDir,
352	      model: this._model,
353	      thinking: this._thinking,
354	      yoloMode: this._yoloMode,
355	      doMode: this._doMode,
356	      executablePath: this._executable,
357	      environmentVariables: envVars,
358	      externalTools: this._externalTools,
359	      agentFile: this._agentFile,
360	      subagentSystemPrompts: this._subagentSystemPrompts,
361	      skillsDir: this._skillsDir,
362	      clientInfo: this._clientInfo,
363	      generationOverrides: this._generationOverrides,
364	    });
365	
366	    this._slashCommands = initResult.slash_commands;
367	    this.activeConfig = currentConfig;
368	
369	    return this.client;
370	  }
371	
372	  private snapshotConfig(): ActiveConfig {
373	    return {
374	      model: this._model,
375	      thinking: this._thinking,
376	      yoloMode: this._yoloMode,
377	      doMode: this._doMode,
378	      executable: this._executable,
379	      env: JSON.stringify(this._env),
380	      externalTools: JSON.stringify(this._externalTools.map((t) => t.name)),
381	      skillsDir: this._skillsDir,
382	      generationOverrides: JSON.stringify(this._generationOverrides),
383	      subagentSystemPrompts: JSON.stringify(this._subagentSystemPrompts),
384	    };
385	  }
386	
387	  private configChanged(current: ActiveConfig): boolean {
388	    const active = this.activeConfig!;
389	    return (
390	      current.model !== active.model ||
391	      current.thinking !== active.thinking ||
392	      current.yoloMode !== active.yoloMode ||
393	      current.doMode !== active.doMode ||
394	      current.executable !== active.executable ||
395	      current.env !== active.env ||
396	      current.externalTools !== active.externalTools ||
397	      current.skillsDir !== active.skillsDir ||
398	      current.generationOverrides !== active.generationOverrides ||
399	      current.subagentSystemPrompts !== active.subagentSystemPrompts
400	    );
401	  }
402	}
