 93	// Event Channel Helper
 94	export function createEventChannel<T>(): {
 95	  iterable: AsyncIterable<T>;
 96	  push: (value: T) => void;
 97	  finish: () => void;
 98	} {
 99	  const queue: T[] = [];
100	  const resolvers: Array<(result: IteratorResult<T>) => void> = [];
101	  let finished = false;
102	
103	  return {
104	    iterable: {
105	      [Symbol.asyncIterator]: () => ({
106	        next: () => {
107	          const queued = queue.shift();
108	          if (queued !== undefined) {
109	            return Promise.resolve({ done: false as const, value: queued });
110	          }
111	          if (finished) {
112	            return Promise.resolve({ done: true as const, value: undefined });
113	          }
114	          return new Promise((resolve) => resolvers.push(resolve));
115	        },
116	      }),
117	    },
118	    push: (value: T) => {
119	      if (finished) {
120	        return;
121	      }
122	      const resolver = resolvers.shift();
123	      if (resolver) {
124	        resolver({ done: false, value });
125	      } else {
126	        queue.push(value);
127	      }
128	    },
129	    finish: () => {
130	      if (finished) {
131	        return;
132	      }
133	      finished = true;
134	      for (const resolver of resolvers) {
135	        resolver({ done: true, value: undefined });
136	      }
137	      resolvers.length = 0;
138	    },
139	  };
140	}
