142	export class ProtocolClient {
143	  private process: ChildProcess | null = null;
144	  private readline: ReadlineInterface | null = null;
145	  private requestId = 0;
146	  private stderrBuffer = "";
147	  private pendingRequests = new Map<string, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();
148	
149	  private pushEvent: ((event: StreamEvent) => void) | null = null;
150	  private finishEvents: (() => void) | null = null;
151	  private externalToolHandlers = new Map<string, ExternalTool["handler"]>();
152	  private hookHandlers = new Map<string, HookHandler>();
153	
154	  get isRunning(): boolean {
155	    return this.process !== null && this.process.exitCode === null;
156	  }
157	
158	  async start(options: ClientOptions): Promise<InitializeResult> {
159	    if (this.process) {
160	      throw new TransportError("ALREADY_STARTED", "Client already started");
161	    }
162	
163	    const args = this.buildArgs(options);
164	    const executable = options.executablePath ?? "consilium";
165	
166	    log.protocol("Spawning CLI: %s %o", executable, args);
167	
168	    try {
169	      const { DEBUG, ...cleanEnv } = process.env;
170	      const { executable: actualExecutable, args: actualArgs } = spawnWindowsSafe(executable, args);
171	      
172	      this.process = spawn(actualExecutable, actualArgs, {
173	        cwd: options.workDir,
174	        env: { ...cleanEnv, ...options.environmentVariables },
175	        stdio: ["pipe", "pipe", "pipe"],
176	      });
177	    } catch (err) {
178	      throw new TransportError("SPAWN_FAILED", `Failed to spawn CLI: ${err}`, err);
179	    }
180	
181	    if (!this.process.stdout || !this.process.stdin) {
182	      this.process.kill();
183	      this.process = null;
184	      throw new TransportError("SPAWN_FAILED", "Process missing stdio");
185	    }
186	
187	    this.readline = createInterface({ input: this.process.stdout });
188	    this.readline.on("line", (line) => this.handleLine(line));
189	
190	    this.process.stderr?.on("data", (data) => {
191	      const chunk = data.toString();
192	      this.stderrBuffer += chunk;
193	      log.protocol("stderr: %s", chunk.trim());
194	    });
195	    this.process.on("error", (err) => this.handleProcessError(err));
196	    this.process.on("exit", (code) => this.handleProcessExit(code));
197	
198	    // Register external tool handlers
199	    if (options.externalTools) {
200	      for (const tool of options.externalTools) {
201	        this.externalToolHandlers.set(tool.name, tool.handler);
202	      }
203	    }
204	
205	    // Register hook handlers
206	    const hookSubscriptions: HookSubscription[] | undefined = options.hooks?.map((h) => {
207	      this.hookHandlers.set(h.id, h.handler);
208	      return { id: h.id, event: h.event, matcher: h.matcher ?? "", timeout: h.timeout ?? 30 };
209	    });
210	
211	    // Send initialize request
212	    const initResult = await this.sendInitialize(options.externalTools, options.clientInfo, hookSubscriptions);
213	    return initResult;
214	  }
215	
216	  async stop(): Promise<void> {
217	    if (!this.process) {
218	      return;
219	    }
220	
221	    if (this.process.exitCode !== null || this.process.killed) {
222	      this.cleanup();
223	      return;
224	    }
225	
226	    log.protocol("Stopping process...");
227	    this.process.kill("SIGTERM");
228	
229	    await new Promise<void>((resolve) => {
230	      const timeout = setTimeout(() => {
231	        this.process?.kill("SIGKILL");
232	        resolve();
233	      }, 3000);
234	
235	      this.process!.once("exit", () => {
236	        clearTimeout(timeout);
237	        resolve();
238	      });
239	    });
240	
241	    this.cleanup();
242	  }
243	
244	  sendPrompt(content: string | ContentPart[]): PromptStream {
245	    const { iterable, push, finish } = createEventChannel<StreamEvent>();
246	
247	    this.pushEvent = push;
248	    this.finishEvents = () => {
249	      finish();
250	      this.pushEvent = null;
251	      this.finishEvents = null;
252	    };
253	
254	    const result = this.sendRequest("prompt", { user_input: content })
255	      .then((res) => {
256	        this.finishEvents?.();
257	        const r = res as { status: string; steps?: number };
258	        return { status: r.status as RunResult["status"], steps: r.steps };
259	      })
260	      .catch((err) => {
261	        this.finishEvents?.();
262	        throw err;
263	      });
264	
265	    return { events: iterable, result };
266	  }
