272	  sendReplay(): ReplayStream {
273	    const { iterable, push, finish } = createEventChannel<StreamEvent>();
274	
275	    this.pushEvent = push;
276	    this.finishEvents = () => {
277	      finish();
278	      this.pushEvent = null;
279	      this.finishEvents = null;
