332	  private async sendInitialize(externalTools?: ExternalTool[], clientInfo?: ClientInfo, hooks?: HookSubscription[]): Promise<InitializeResult> {
333	    let clientName = `${SDK_NAME}/${SDK_VERSION}`;
334	    if (clientInfo?.name && clientInfo?.version) {
335	      clientName += ` ${clientInfo.name}/${clientInfo.version}`;
336	    }
337	
338	    const params: Record<string, unknown> = {
339	      protocol_version: PROTOCOL_VERSION,
340	      client: {
341	        name: clientName,
342	        version: SDK_VERSION,
343	      },
344	      capabilities: {
345	        supports_question: true,
346	        supports_plan_mode: true,
347	      },
348	    };
349	
350	    if (externalTools && externalTools.length > 0) {
351	      params.external_tools = externalTools.map((tool) => ({
352	        name: tool.name,
353	        description: tool.description,
354	        parameters: tool.parameters,
355	      }));
356	    }
357	
358	    if (hooks && hooks.length > 0) {
359	      params.hooks = hooks.map((h) => ({
360	        id: h.id,
361	        event: h.event,
362	        matcher: h.matcher ?? "",
363	        timeout: h.timeout ?? 30,
364	      }));
365	    }
366	
367	    log.protocol("Sending initialize request: %O", params);
368	    const result = await this.sendRequest("initialize", params);
369	    const parsed = InitializeResultSchema.safeParse(result);
370	
371	    log.protocol("Received initialize response: %O", result);
372	    if (!parsed.success) {
373	      throw new TransportError("SPAWN_FAILED", `Invalid initialize response: ${parsed.error.message}`);
374	    }
375	
376	    log.protocol("Initialized: protocol=%s, server=%s/%s", parsed.data.protocol_version, parsed.data.server.name, parsed.data.server.version);
377	
378	    return parsed.data;
379	  }
