429	  // Private: RPC Communication
430	  private sendRequest(method: string, params?: any): Promise<unknown> {
431	    const id = `${++this.requestId}_${Date.now()}`;
432	
433	    return new Promise((resolve, reject) => {
434	      this.pendingRequests.set(id, { resolve, reject });
435	
436	      try {
437	        this.writeLine({ jsonrpc: "2.0", id, method, ...(params && { params }) });
438	      } catch (err) {
439	        this.pendingRequests.delete(id);
440	        reject(err);
441	      }
442	    });
443	  }
444	
445	  private writeLine(data: unknown): void {
446	    log.protocol(">>> %O", data);
447	
448	    if (!this.process?.stdin?.writable) {
449	      throw new TransportError("STDIN_NOT_WRITABLE", "Cannot write to CLI stdin");
450	    }
451	    this.process.stdin.write(JSON.stringify(data) + "\n");
452	  }
453	
454	  // Private: Line Handling
455	  private handleLine(line: string): void {
456	    log.protocol("<<< %s", line.length > 500 ? line.slice(0, 500) + "..." : line);
457	
458	    let parsed: unknown;
459	    try {
460	      parsed = JSON.parse(line);
461	    } catch {
462	      this.emitParseError("INVALID_JSON", "Failed to parse JSON", line);
463	      return;
464	    }
465	
466	    const msg = parsed as {
467	      id?: string;
468	      method?: string;
469	      params?: unknown;
470	      result?: unknown;
471	      error?: { code: number; message: string };
472	    };
473	
474	    // Response to a pending request
475	    if (msg.id && this.pendingRequests.has(msg.id)) {
476	      const pending = this.pendingRequests.get(msg.id)!;
477	      this.pendingRequests.delete(msg.id);
478	
479	      if (msg.error) {
480	        pending.reject(CliError.fromRpcError(msg.error.code, msg.error.message, JSON.stringify(msg)));
481	      } else {
482	        pending.resolve(msg.result);
483	      }
484	      return;
485	    }
486	
487	    // Notification (event or request from server)
488	    if (msg.method) {
489	      if (msg.method === "request" && msg.id) {
490	        this.handleServerRequest(msg.id, msg.params);
491	      } else {
492	        this.handleNotification(msg.method, msg.params);
493	      }
494	    }
495	  }
496	
497	  private handleNotification(method: string, params: unknown): void {
498	    if (method === "event") {
499	      const p = params as { type?: string; payload?: unknown } | undefined;
500	      if (!p?.type) {
501	        this.emitParseError("SCHEMA_MISMATCH", "Event missing type");
502	        return;
503	      }
504	      const result = parseEventPayload(p.type, p.payload);
505	      if (result.ok) {
506	        this.pushEvent?.(result.value);
507	      } else {
508	        this.emitParseError("UNKNOWN_EVENT_TYPE", result.error);
509	      }
510	    }
511	  }
512	
513	  private handleServerRequest(requestId: string, params: unknown): void {
514	    const p = params as { type?: string; payload?: unknown } | undefined;
515	    if (!p?.type) {
516	      this.emitParseError("SCHEMA_MISMATCH", "Request missing type");
517	      return;
518	    }
519	
520	    if (p.type === "ToolCallRequest") {
521	      this.handleToolCallRequest(requestId, p.payload as ToolCallRequest);
522	      return;
523	    }
524	
525	    if (p.type === "HookRequest") {
526	      this.handleHookRequest(requestId, p.payload as HookRequest);
527	      return;
528	    }
529	
530	    // For other request types (ApprovalRequest, QuestionRequest), emit as event
531	    const result = parseRequestPayload(p.type, p.payload);
532	    if (result.ok) {
533	      this.pushEvent?.(result.value);
534	    } else {
535	      this.emitParseError("UNKNOWN_REQUEST_TYPE", result.error);
536	    }
537	  }
538	
539	  private async handleToolCallRequest(requestId: string, request: ToolCallRequest): Promise<void> {
540	    const handler = this.externalToolHandlers.get(request.name);
541	
542	    let returnValue: ToolReturnValue;
543	
544	    if (!handler) {
545	      returnValue = {
546	        is_error: true,
547	        output: `Unknown external tool: ${request.name}`,
548	        message: `Tool "${request.name}" is not registered`,
549	        display: [],
550	      };
551	    } else {
552	      try {
553	        const params = request.arguments ? JSON.parse(request.arguments) : {};
554	        const result = await handler(params);
555	        returnValue = {
556	          is_error: false,
557	          output: result.output,
558	          message: result.message,
559	          display: [],
560	        };
561	      } catch (err) {
562	        const message = err instanceof Error ? err.message : String(err);
563	        returnValue = {
564	          is_error: true,
565	          output: message,
566	          message: `Tool execution failed: ${message}`,
567	          display: [],
568	        };
569	      }
570	    }
571	
572	    this.writeLine({
573	      jsonrpc: "2.0",
574	      id: requestId,
575	      result: {
576	        tool_call_id: request.id,
577	        return_value: returnValue,
578	      },
579	    });
580	  }
581	
582	  private async handleHookRequest(requestId: string, request: HookRequest): Promise<void> {
583	    let action: "allow" | "block" = "allow";
584	    let reason = "";
585	
586	    // Dispatch by subscription_id to the registered handler
587	    const handler = this.hookHandlers.get(request.subscription_id);
588	    if (handler) {
589	      try {
590	        const result = await handler(request);
591	        action = result.action;
592	        reason = result.reason ?? "";
593	      } catch (err) {
594	        log.protocol("Hook handler error for subscription %s: %O", request.subscription_id, err);
595	        // Fail-open: allow on handler error
596	        action = "allow";
597	      }
598	    } else {
599	      // No handler for this subscription — emit as event so Turn iterator can see it
600	      const parsed = parseRequestPayload("HookRequest", request);
601	      if (parsed.ok) {
602	        this.pushEvent?.(parsed.value);
603	      }
604	    }
605	
606	    this.writeLine({
607	      jsonrpc: "2.0",
608	      id: requestId,
609	      result: {
610	        request_id: request.id,
611	        action,
612	        reason,
613	      },
614	    });
615	  }
616	
617	  private emitParseError(code: string, message: string, raw?: string): void {
618	    const error: ParseError = { type: "error", code, message, raw: raw?.slice(0, 500) };
619	    this.pushEvent?.(error);
620	  }
621	
622	  // Private: Process Lifecycle
623	  private handleProcessError(err: Error): void {
624	    log.protocol("Process error: %s", err.message);
625	
626	    const error = new TransportError("PROCESS_CRASHED", `CLI process error: ${err.message}`, err);
627	    for (const pending of this.pendingRequests.values()) {
628	      pending.reject(error);
629	    }
630	    this.finishEvents?.();
631	    this.cleanup();
632	  }
633	
634	  private handleProcessExit(code: number | null): void {
635	    log.protocol("Process exited with code: %d", code);
636	    if (code !== 0 && code !== null) {
637	      const errorMsg = this.stderrBuffer.trim() ? `CLI exited with code ${code}: ${this.stderrBuffer.trim()}` : `CLI exited with code ${code}`;
638	      const error = new TransportError("PROCESS_CRASHED", errorMsg);
639	
640	      for (const pending of this.pendingRequests.values()) {
641	        pending.reject(error);
642	      }
643	    }
644	    this.finishEvents?.();
645	    this.cleanup();
646	  }
647	
648	  private cleanup(): void {
649	    this.readline?.removeAllListeners();
650	    this.readline?.close();
651	    this.readline = null;
652	
653	    this.process?.removeAllListeners();
654	    this.process?.stdout?.removeAllListeners();
655	    this.process?.stderr?.removeAllListeners();
656	    this.process = null;
657	
658	    this.pushEvent = null;
659	    this.finishEvents = null;
660	    this.pendingRequests.clear();
661	    this.externalToolHandlers.clear();
662	  }
663	}

