 71	/** List sessions from all registered workDirs under a workspace */
 72	export async function listSessionsForWorkspace(workspaceRoot: string): Promise<SessionInfo[]> {
 73	  const workDirs = getRegisteredWorkDirs(workspaceRoot);
 74	  const allSessions: SessionInfo[] = [];
 75	
 76	  for (const workDir of workDirs) {
 77	    const sessions = await listSessions(workDir);
 78	    allSessions.push(...sessions);
 79	  }
 80	
 81	  // Also include Think sessions so they appear in the history list
 82	  const thinkSessions = await listThinkSessions(workspaceRoot);
 83	  allSessions.push(...thinkSessions);
 84	
 85	  return allSessions.sort((a, b) => b.updatedAt - a.updatedAt);
 86	}
