159	    entries = await fsp.readdir(sessionsDir, { withFileTypes: true });
160	  } catch (err) {
161	    console.warn("[storage] Failed to read sessions:", err);
162	    return [];
163	  }
164	
165	  const sessions: SessionInfo[] = [];
