229	// Get First User Message (Stream-based, early exit)
230	async function getFirstUserMessage(wireFile: string): Promise<string> {
231	  try {
232	    const stream = fs.createReadStream(wireFile, { encoding: "utf-8" });
233	    const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
234	
235	    for await (const line of rl) {
236	      if (!line.trim()) {
237	        continue;
238	      }
239	
240	      try {
241	        const record = JSON.parse(line);
242	        if (record.message?.type !== "TurnBegin") {
243	          continue;
244	        }
245	
246	        const userInput = record.message.payload?.user_input;
247	        const text = extractUserText(userInput);
248	        if (text) {
249	          rl.close();
250	          stream.destroy();
251	          return text;
252	        }
253	      } catch {
254	        continue;
255	      }
256	    }
257	  } catch (err) {
258	    log.storage("Failed to read wire file: %O", err);
259	  }
260	
261	  return "";
262	}
263	
264	// Text Extraction Helpers
265	function extractUserText(userInput: unknown): string {
266	  if (typeof userInput === "string") {
267	    return stripFileTags(userInput);
268	  }
269	
270	  if (Array.isArray(userInput)) {
271	    const textParts = (userInput as ContentPart[]).filter((p): p is ContentPart & { type: "text" } => p.type === "text").map((p) => p.text);
272	    return stripFileTags(textParts.join("\n"));
273	  }
274	
275	  return "";
276	}
277	
278	function stripFileTags(text: string): string {
279	  return text
280	    .replace(/<uploaded_files>[\s\S]*?<\/uploaded_files>\s*/g, "")
281	    .replace(/<document[^>]*>[\s\S]*?<\/document>\s*/g, "")
282	    .replace(/<image[^>]*>[\s\S]*?<\/image>\s*/g, "")
283	    .trim();
284	}
