286	/** Extract first non-empty user message from a Think session JSONL file. */
287	async function getFirstUserMessageFromThinkFile(filePath: string): Promise<string> {
288	  try {
289	    const stream = fs.createReadStream(filePath, { encoding: "utf-8" });
290	    const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
291	
292	    for await (const line of rl) {
293	      if (!line.trim()) {
294	        continue;
295	      }
296	
297	      try {
298	        const record = JSON.parse(line);
299	        if (record.role !== "user") {
300	          continue;
301	        }
302	
303	        const text = typeof record.content === "string" ? record.content : "";
304	        const stripped = stripFileTags(text);
305	        if (stripped) {
306	          rl.close();
307	          stream.destroy();
308	          return stripped;
309	        }
310	      } catch {
311	        continue;
312	      }
313	    }
314	  } catch (err) {
315	    log.storage("Failed to read think session file: %O", err);
316	  }
317	
318	  return "";
319	}
