321	// Fork Session
322	export async function forkSession(options: ForkSessionOptions): Promise<ForkSessionResult> {
323	  const { workDir, sourceSessionId, turnIndex } = options;
324	
325	  if (!UUID_REGEX.test(sourceSessionId)) {
326	    throw new Error(`Invalid session ID: ${sourceSessionId}`);
327	  }
328	
329	  if (turnIndex < 0) {
330	    throw new Error(`Invalid turn index: ${turnIndex}`);
331	  }
332	
333	  const sourceDir = ConsiliumPaths.sessionDir(workDir, sourceSessionId);
334	  const sourceWireFile = path.join(sourceDir, "wire.jsonl");
335	  const sourceContextFile = path.join(sourceDir, "context.jsonl");
336	
337	  // Verify source session exists
338	  try {
339	    await fsp.access(sourceWireFile);
340	  } catch {
341	    throw new Error(`Source session not found: ${sourceSessionId}`);
342	  }
343	
344	  // Create new session
345	  const newSessionId = crypto.randomUUID();
346	  const newSessionDir = ConsiliumPaths.sessionDir(workDir, newSessionId);
347	
348	  await fsp.mkdir(newSessionDir, { recursive: true });
349	
350	  // Truncate wire.jsonl at the specified turn
351	  const wireLines = await truncateWireAtTurn(sourceWireFile, turnIndex);
352	  if (wireLines.length === 0) {
353	    await fsp.rm(newSessionDir, { recursive: true, force: true });
354	    throw new Error(`Turn ${turnIndex} not found in session`);
355	  }
356	
357	  await fsp.writeFile(path.join(newSessionDir, "wire.jsonl"), wireLines.join("\n") + "\n");
358	
359	  // Truncate context.jsonl if it exists
360	  try {
361	    await fsp.access(sourceContextFile);
362	    const contextLines = await truncateContextAtTurn(sourceContextFile, turnIndex);
363	    if (contextLines.length > 0) {
364	      await fsp.writeFile(path.join(newSessionDir, "context.jsonl"), contextLines.join("\n") + "\n");
365	    }
366	  } catch {
367	    // context.jsonl doesn't exist or is empty, that's fine
368	  }
369	
370	  log.storage("Forked session %s -> %s at turn %d", sourceSessionId, newSessionId, turnIndex);
371	
372	  return {
373	    sessionId: newSessionId,
374	    sessionDir: newSessionDir,
375	  };
376	}
