378	/**
379	 * Truncate wire.jsonl to include only complete turns up to the specified turn index.
380	 * If the target turn is incomplete (no TurnEnd), it will be discarded to prevent
381	 * API errors from incomplete tool calls.
382	 */
383	async function truncateWireAtTurn(wireFile: string, turnIndex: number): Promise<string[]> {
384	  const lines: string[] = [];
385	  let turnCount = 0;
386	  let lastTurnEndIndex = -1;
387	
388	  const stream = fs.createReadStream(wireFile, { encoding: "utf-8" });
389	  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
390	
391	  for await (const line of rl) {
392	    if (!line.trim()) {
393	      continue;
394	    }
395	
396	    try {
397	      const record = JSON.parse(line);
398	      const messageType = record.message?.type;
399	
400	      if (messageType === "TurnBegin") {
401	        if (turnCount > turnIndex) {
402	          break;
403	        }
404	        turnCount++;
405	      }
406	
407	      lines.push(line);
408	
409	      // Track the last TurnEnd position
410	      if (messageType === "TurnEnd" && turnCount === turnIndex + 1) {
411	        lastTurnEndIndex = lines.length;
412	        break;
413	      }
414	    } catch {
415	      if (turnCount > 0 && turnCount <= turnIndex + 1) {
416	        lines.push(line);
417	      }
418	    }
419	  }
420	
421	  rl.close();
422	  stream.destroy();
423	
424	  // If target turn completed normally, return all lines
425	  if (lastTurnEndIndex > 0) {
426	    return lines.slice(0, lastTurnEndIndex);
427	  }
428	
429	  // Target turn is incomplete - find the last complete turn
430	  // Scan backwards for the last TurnEnd
431	  for (let i = lines.length - 1; i >= 0; i--) {
432	    try {
433	      const record = JSON.parse(lines[i]);
434	      if (record.message?.type === "TurnEnd") {
435	        log.storage("Target turn incomplete, truncating to last complete turn");
436	        return lines.slice(0, i + 1);
437	      }
438	    } catch {
439	      continue;
440	    }
441	  }
442	
443	  // No complete turn found - return empty or just the first TurnBegin
444	  // to allow user to continue from scratch
445	  log.storage("No complete turn found in session");
446	  return [];
447	}
448	
449	/**
450	 * Truncate context.jsonl to include only messages up to and including the specified turn.
451	 * If the last assistant message has incomplete tool_calls, it will be removed.
452	 */
453	async function truncateContextAtTurn(contextFile: string, turnIndex: number): Promise<string[]> {
454	  const lines: string[] = [];
455	  let userMessageCount = 0;
456	
457	  const stream = fs.createReadStream(contextFile, { encoding: "utf-8" });
458	  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
459	
460	  for await (const line of rl) {
461	    if (!line.trim()) {
462	      continue;
463	    }
464	
465	    try {
466	      const record = JSON.parse(line);
467	      const role = record.role;
468	
469	      // Always include markers
470	      if (role === "_checkpoint" || role === "_usage") {
471	        lines.push(line);
472	        continue;
473	      }
474	
475	      if (role === "user") {
476	        if (userMessageCount > turnIndex) {
477	          break;
478	        }
479	        userMessageCount++;
480	      } else if (role === "assistant" && userMessageCount > turnIndex + 1) {
481	        break;
482	      }
483	
484	      lines.push(line);
485	    } catch {
486	      lines.push(line);
487	    }
488	  }
489	
490	  rl.close();
491	  stream.destroy();
492	
493	  // Check if last assistant has incomplete tool_calls
494	  return removeIncompleteToolCalls(lines);
495	}
496	
497	/**
498	 * Remove assistant messages with incomplete tool_calls (missing tool responses).
499	 */
500	function removeIncompleteToolCalls(lines: string[]): string[] {
501	  // Collect tool_call IDs from assistant messages and tool responses
502	  const expectedIds = new Set<string>();
503	  const receivedIds = new Set<string>();
504	  const assistantIndicesWithToolCalls: number[] = [];
505	
506	  for (let i = 0; i < lines.length; i++) {
507	    try {
508	      const record = JSON.parse(lines[i]);
509	      if (record.role === "assistant" && Array.isArray(record.tool_calls)) {
510	        for (const tc of record.tool_calls) {
511	          if (tc.id) expectedIds.add(tc.id);
512	        }
513	        if (record.tool_calls.length > 0) {
514	          assistantIndicesWithToolCalls.push(i);
515	        }
516	      } else if (record.role === "tool" && record.tool_call_id) {
517	        receivedIds.add(record.tool_call_id);
518	      }
519	    } catch {
520	      continue;
521	    }
522	  }
523	
524	  // Check if all tool_calls have responses
525	  const hasIncomplete = [...expectedIds].some((id) => !receivedIds.has(id));
526	  if (!hasIncomplete) {
527	    return lines;
528	  }
529	
530	  // Find the last assistant with incomplete tool_calls and truncate before it
531	  for (let i = assistantIndicesWithToolCalls.length - 1; i >= 0; i--) {
532	    const idx = assistantIndicesWithToolCalls[i];
533	    try {
534	      const record = JSON.parse(lines[idx]);
535	      const ids = (record.tool_calls || []).map((tc: { id?: string }) => tc.id).filter(Boolean);
536	      const incomplete = ids.some((id: string) => !receivedIds.has(id));
537	      if (incomplete) {
538	        log.storage("Removing incomplete assistant message at index %d", idx);
539	        // Keep lines before this assistant, plus any markers after
540	        const before = lines.slice(0, idx);
541	        const after = lines.slice(idx + 1).filter((l) => {
542	          try {
543	            const r = JSON.parse(l);
544	            return r.role === "_checkpoint" || r.role === "_usage";
545	          } catch {
546	            return false;
547	          }
548	        });
549	        return [...before, ...after];
550	      }
551	    } catch {
552	      continue;
553	    }
554	  }
555	
556	  return lines;
557	}

  1	/**
  2	 * Generate a concise session title from the first user message and assistant reply.
  3	 *
  4	 * Uses a short-lived, temporary CLI session so the title-generation prompt does not
  5	 * pollute the real session history. The temporary session directory and any CLI-side
  6	 * session file (e.g. ~/.consilium/think_sessions/<id>.jsonl) are removed after the call.
  7	 */
  8	
  9	import * as fs from "node:fs";
 10	import * as os from "node:os";
 11	import * as path from "node:path";
 12	import { createSession, type StreamEvent } from "@consilium/agent-sdk";
 13	import { getCLIManager } from "../managers";
 14	import { VSCodeSettings } from "../config/vscode-settings";
 15	import { handlerLog } from "../utils/logger.js";
 16	
 17	const TITLE_MAX_TOKENS = 20;
 18	const TITLE_GENERATION_PROMPT_SNIPPET =
 19	  "Summarize the following user request and assistant reply in 4-6 words as a chat title";
 20	
 21	export interface TitleGenerationInputs {
 22	  firstUserText: string;
 23	  firstAssistantText: string;
 24	  model: string;
 25	  mode?: "think" | "do";
 26	}
 27	
 28	function collectTextFromEvent(event: StreamEvent): string {
 29	  if (event.type === "ContentPart") {
 30	    const part = event.payload as { type?: string; text?: string };
 31	    if (part?.type === "text" && typeof part.text === "string") {
 32	      return part.text;
 33	    }
 34	  }
 35	  return "";
 36	}
 37	
 38	function removeTempSessionFiles(sessionId: string, doMode: boolean): void {
 39	  try {
 40	    if (doMode) {
 41	      const doDir = path.join(os.homedir(), ".consilium", "do_sessions", sessionId);
 42	      if (fs.existsSync(doDir)) {
 43	        fs.rmSync(doDir, { recursive: true, force: true });
 44	      }
 45	    } else {
 46	      const thinkFile = path.join(os.homedir(), ".consilium", "think_sessions", `${sessionId}.jsonl`);
 47	      if (fs.existsSync(thinkFile)) {
 48	        fs.rmSync(thinkFile, { force: true });
 49	      }
 50	    }
 51	  } catch (err) {
 52	    handlerLog.warn("Failed to clean up temp title session file", { sessionId, error: String(err) });
 53	  }
 54	}
 55	
 56	export async function generateTitleForSession(
 57	  inputs: TitleGenerationInputs,
 58	): Promise<string | null> {
 59	  const { firstUserText, firstAssistantText, model, mode } = inputs;
 60	
 61	  const cli = getCLIManager();
 62	  const executable = cli.getExecutablePath();
 63	  const env = VSCodeSettings.environmentVariables;
 64	  const version = VSCodeSettings.getExtensionConfig().version;
 65	
 66	  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "consilium-title-"));
 67	  const doMode = mode === "do";
 68	
 69	  let session: ReturnType<typeof createSession> | undefined;
 70	
 71	  try {
 72	    session = createSession({
 73	      workDir: tempDir,
 74	      model,
 75	      thinking: false,
 76	      yoloMode: false,
 77	      doMode,
 78	      executable,
 79	      env,
 80	      clientInfo: { name: "consilium-code-for-vs-code-title", version },
 81	      generationOverrides: {
 82	        // Do not override temperature: some models only accept a fixed value
 83	        // (e.g. 0.6). Let the CLI use the model default.
 84	        maxTokens: TITLE_MAX_TOKENS,
 85	      },
 86	    });
 87	
 88	    const prompt = [
 89	      `${TITLE_GENERATION_PROMPT_SNIPPET}.`,
 90	      "Reply with only the title, no quotes or punctuation.",
 91	      "",
 92	      `User: ${firstUserText}`,
 93	      `Assistant: ${firstAssistantText}`,
 94	    ].join("\n");
 95	
 96	    const turn = session.prompt(prompt);
 97	    const chunks: string[] = [];
 98	
 99	    for await (const event of turn) {
100	      const text = collectTextFromEvent(event as StreamEvent);
101	      if (text) {
102	        chunks.push(text);
103	      }
104	    }
105	
106	    await turn.result;
