 4	/**
 5	 * Rewrites executable + args for Windows .cmd/.bat wrappers.
 6	 * On Windows, spawning a .cmd/.bat file directly fails with EINVAL,
 7	 * so we delegate to cmd.exe /d /s /c <script> [args...].
 8	 *
 9	 * Returns the possibly-modified executable and args.
10	 * Throws TransportError if ComSpec/cmd.exe is missing.
11	 */
12	export function spawnWindowsSafe(
13	  executable: string,
14	  args: string[],
15	): { executable: string; args: string[] } {
16	  if (process.platform !== "win32") {
17	    return { executable, args };
18	  }
19	
20	  const lower = executable.toLowerCase();
21	  if (!lower.endsWith(".cmd") && !lower.endsWith(".bat")) {
22	    return { executable, args };
23	  }
24	
25	  const comspec = process.env.ComSpec || "cmd.exe";
26	  if (!existsSync(comspec)) {
27	    throw new TransportError(
28	      "SPAWN_FAILED",
29	      `Windows spawn failed: ComSpec/cmd.exe not found at "${comspec}". ` +
30	        `Cannot execute "${executable}".`,
31	    );
32	  }
33	
34	  return {
35	    executable: comspec,
36	    args: ["/d", "/s", "/c", executable, ...args],
