## 1. Session Creation Flow

### Entry: `createSession()` in `agent_sdk/session.ts`
```typescript
// agent_sdk/session.ts:405-407
export function createSession(options: SessionOptions): Session {
  return new SessionImpl(options);
}
```

The `SessionImpl` constructor (`session.ts:186-204`):
```typescript
constructor(options: SessionOptions) {
  this._sessionId = options.sessionId ?? crypto.randomUUID();
  this._workDir = options.workDir;
  this._model = options.model;
  this._thinking = options.thinking ?? false;
  this._yoloMode = options.yoloMode ?? false;
  this._doMode = options.doMode ?? false;
  this._executable = options.executable ?? "consilium";
  this._env = options.env ?? {};
  this._externalTools = options.externalTools ?? [];
  this._agentFile = options.agentFile;
  this._subagentSystemPrompts = options.subagentSystemPrompts;
  this._skillsDir = options.skillsDir;
  this._shareDir = options.shareDir;
  this._clientInfo = options.clientInfo;
  this._generationOverrides = options.generationOverrides;
}
```

**Key:** The session is **lazy** — it does NOT spawn a CLI process until `prompt()` is called and a message needs to be sent.

### Who calls `createSession` — The Bridge `getOrCreateSession()`

In `bridge-handler.ts:331-417`, the `getOrCreateSession` method is the **central orchestration point** called from `chat.handler.ts:179`:

```typescript
// bridge-handler.ts:331
private async getOrCreateSession(
  webviewId: string, model: string, thinking: boolean,
  sessionId?: string, mode?: 'think' | 'do'
): Promise<Session> {
  const workDir = this.requireWorkDir(webviewId); // MUST have a workspace
  const cli = getCLIManager();
  const config = parseConfig();

  // Determine actual thinking state based on model capability
  const modelConfig = getModelById(config.models, model);
  const thinkingMode = modelConfig ? getModelThinkingMode(modelConfig) : "none";

  const executable = cli.getExecutablePath();
  const env = VSCodeSettings.environmentVariables;
  const globalYoloMode = VSCodeSettings.yoloMode;
  const requestedMode = mode ?? 'think';
  const actualDoMode = requestedMode === 'do';
  const actualYoloMode = actualDoMode ? true : globalYoloMode;  // Do-mode forces yolo
  const generationConfig = VSCodeSettings.generationConfig;

  // Partition sessions by key: Think=webviewId, Do=webviewId:do
  const key = requestedMode === 'do' ? `${webviewId}:do` : webviewId;
  const agentFile = resolveAgentFile(requestedMode, this.workspaceRoot, this.extensionRoot);
  const subagentSystemPrompts = resolveSubagentRoleOverrides(this.workspaceRoot, this.extensionRoot);

  // ... existing session restart logic ...

  const session = createSession({
    workDir,
    model,
    thinking: actualThinking,
    yoloMode: actualYoloMode,
    doMode: actualDoMode,
    sessionId,
    executable,
    env,
    agentFile,
    subagentSystemPrompts,
    clientInfo: { name: "consilium-code-for-vs-code", version: VSCodeSettings.getExtensionConfig().version },
    generationOverrides: /* ... */,
  });

  this.sessions.set(key, session);
  this.fileManager.setSessionId(key, session.sessionId);
  this.persistTabState(webviewId);
  return session;
}
```

### When `prompt()` triggers CLI spawn

When the webview sends `StreamChat`, the handler in `chat.handler.ts:142-348` calls:

```typescript
// chat.handler.ts:179
const session = await ctx.getOrCreateSession(params.model, params.thinking, params.sessionId, params.mode);
// ...
const turn = session.prompt(contentWithContext);
```

This calls `SessionImpl.prompt()` which queues the message. On first call, `getClientWithConfigCheck()` is invoked (`session.ts:333-370`):

```typescript
private async getClientWithConfigCheck(): Promise<ProtocolClient> {
  const currentConfig = this.snapshotConfig();
  if (this.client?.isRunning && this.activeConfig && !this.configChanged(currentConfig)) {
    return this.client;
  }

  // Config changed or no client → restart
  this.client = new ProtocolClient();
  const envVars = this._shareDir
    ? { KIMI_SHARE_DIR: this._shareDir, ...this._env }
    : this._env;

  const initResult = await this.client.start({
    sessionId: this._sessionId,
    workDir: this._workDir,
    model: this._model,
    thinking: this._thinking,
    yoloMode: this._yoloMode,
    doMode: this._doMode,
    executablePath: this._executable,
    environmentVariables: envVars,
    externalTools: this._externalTools,
    agentFile: this._agentFile,
    subagentSystemPrompts: this._subagentSystemPrompts,
    skillsDir: this._skillsDir,
    clientInfo: this._clientInfo,
    generationOverrides: this._generationOverrides,
  });

  this._slashCommands = initResult.slash_commands;
  this.activeConfig = currentConfig;
  return this.client;
}
```

This is where `ProtocolClient.start()` is called, which THEN spawns the CLI process.

